     * # Errors
     *
     * A storage-layer failure.
     */
    @Throws(CoreException::class)override fun `readLegacyQueue`(): kotlin.String? {
            return FfiConverterOptionalString.lift(
    callWithHandle {
    uniffiRustCallWithError(CoreException) { _status ->
