public object FfiConverterTypeMigrationStorage: FfiConverter<MigrationStorage, Long> {
    internal val handleMap = UniffiHandleMap<MigrationStorage>()

    override fun lower(value: MigrationStorage): Long {
        if (value is MigrationStorageImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): MigrationStorage {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return MigrationStorageImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): MigrationStorage {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: MigrationStorage) = 8UL

    override fun write(value: MigrationStorage, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


