        /**
         * When the user made the change, in epoch milliseconds.
         */
        val `createdAt`: kotlin.Long, 
        /**
         * The client-minted id the optimistic task is shown under.
         */
        val `tempId`: uniffi.TaskNotesCore.TaskId, 
        /**
         * What to create.
         */
        val `payload`: uniffi.TaskNotesCore.CreateTaskRequest) : Command()
        
    {
        

        companion object
    }
    
    /**
     * Apply a partial update to an existing task.
     */
    data class Update(
        /**
         * The idempotency key, unique across restarts.
         */
        val `id`: kotlin.String, 
        /**
         * When the user made the change, in epoch milliseconds.
         */
        val `createdAt`: kotlin.Long, 
        /**
         * The task to update.
         */
        val `taskId`: uniffi.TaskNotesCore.TaskId, 
        /**
         * The three-state partial update.
         */
        val `payload`: uniffi.TaskNotesCore.UpdateTaskRequest) : Command()
        
    {
        

        companion object
    }
    
    /**
     * Delete a task.
     */
    data class Delete(
        /**
         * The idempotency key, unique across restarts.
         */
        val `id`: kotlin.String, 
        /**
         * When the user made the change, in epoch milliseconds.
         */
        val `createdAt`: kotlin.Long, 
        /**
         * The task to delete.
         */
        val `taskId`: uniffi.TaskNotesCore.TaskId) : Command()
        
    {
        

        companion object
    }
    
    /**
     * Set a task's status to an absolute value.
     */
    data class SetStatus(
        /**
         * The idempotency key, unique across restarts.
         */
        val `id`: kotlin.String, 
        /**
         * When the user made the change, in epoch milliseconds.
         */
        val `createdAt`: kotlin.Long, 
        /**
         * The task to restatus.
         */
        val `taskId`: uniffi.TaskNotesCore.TaskId, 
        /**
         * The status to set. Absolute, never derived from the current one.
         */
        val `status`: uniffi.TaskNotesCore.TaskStatus) : Command()
        
    {
        

        companion object
    }
    
    /**
     * Set one occurrence of a recurring task to an absolute completion state.
     */
    data class SetInstanceComplete(
        /**
         * The idempotency key, unique across restarts.
         */
        val `id`: kotlin.String, 
        /**
         * When the user made the change, in epoch milliseconds.
         */
        val `createdAt`: kotlin.Long, 
        /**
         * The recurring task.
         */
        val `taskId`: uniffi.TaskNotesCore.TaskId, 
        /**
         * The occurrence's date, as `YYYY-MM-DD`.
         */
        val `date`: kotlin.String, 
        /**
         * The state to set the occurrence to.
         */
        val `completed`: kotlin.Boolean, 
        /**
         * The recurring schedule an uncompletion puts back, when the core
         * captured one. Always absent on a completion.
         */
        val `restore`: uniffi.TaskNotesCore.InstanceRestore?) : Command()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeCommand : FfiConverterRustBuffer<Command>{
    override fun read(buf: ByteBuffer): Command {
        return when(buf.getInt()) {
            1 -> Command.Create(
                FfiConverterString.read(buf),
                FfiConverterLong.read(buf),
                FfiConverterTypeTaskId.read(buf),
                FfiConverterTypeCreateTaskRequest.read(buf),
