        /**
         * What the platform reported.
         */
        val `detail`: kotlin.String
        ) : TransportException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * The host could not reach the network or the server at all.
     */
    class Offline(
        
        /**
         * What the platform reported.
         */
        val `detail`: kotlin.String
        ) : TransportException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * The TLS handshake or certificate validation failed.
     */
